def _poly_add(P, Q):
    R = dict(P)
    for k, v in Q.items():
        R[k] = R.get(k, Fraction(0)) + v
        if R[k] == 0:
            R.pop(k)
    return R

def _poly_sub(P, Q):
    R = dict(P)
    for k, v in Q.items():
        R[k] = R.get(k, Fraction(0)) - v
        if R[k] == 0:
            R.pop(k)
    return R

def _poly_scale(P, c):
    return {k: v*c for k, v in P.items()}

def _poly_shift(P, s):
    return {k+s: v for k, v in P.items()}

def chebyshev_T(n):
    # T_0(x) = 1, T_1(x) = x, T_{n+1}(x) = 2x T_n(x) - T_{n-1}(x)
    T = [{0: Fraction(1)}, {1: Fraction(1)}]
    for k in range(1, n):
        two_x_Tk = _poly_shift(_poly_scale(T[k], Fraction(2)), 1)
        Tk1 = _poly_sub(two_x_Tk, T[k-1])
        T.append(Tk1)
    return T[n]

def monomial(deg, coeff):
    return {deg: Fraction(coeff)}

