    d = {}
    for k in range(m-2, 0, -2):
        Tk = chebyshev_T(k)
        lead = Fraction(2**(k-1))  # Leading coeff of T_k
        coeff_k = R.get(k, Fraction(0))
        if coeff_k != 0:
            dk = coeff_k / lead
            d[k] = dk
            # R -= dk * Tk
            R = _poly_sub(R, _poly_scale(Tk, dk))
    # After elimination, remainder should be zero
    if R:
        # Allow tiny numerical residue only if exactly zero
        # Here R contains Fractions, so must be exactly empty
        raise ValueError("Elimination failed; remainder nonzero")
    return d

